CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE sessions(session_id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE principals(token_hash TEXT PRIMARY KEY, principal_id TEXT NOT NULL, role TEXT NOT NULL, session_id TEXT, allowed_run_ids_json TEXT NOT NULL, allowed_shop_ids_json TEXT NOT NULL, allowed_job_ids_json TEXT NOT NULL);
CREATE TABLE runs(run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), scenario_version TEXT NOT NULL, schema_version INTEGER NOT NULL, simulator_version TEXT NOT NULL, seed INTEGER NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('offline','replay','live')), memory_enabled INTEGER NOT NULL, history_days INTEGER NOT NULL, simulation_days INTEGER NOT NULL CHECK(simulation_days IN (6,7)), start_date TEXT NOT NULL, current_day INTEGER NOT NULL, phase TEXT NOT NULL, source_run_id TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE shops(run_id TEXT NOT NULL REFERENCES runs(run_id), shop_id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,shop_id));
CREATE TABLE products(run_id TEXT NOT NULL, product_id TEXT NOT NULL, shop_id TEXT NOT NULL, name TEXT NOT NULL, list_price_vnd INTEGER NOT NULL CHECK(list_price_vnd>0), facts_json TEXT NOT NULL CHECK(json_valid(facts_json)), listing_quality REAL NOT NULL, search_rank_page INTEGER NOT NULL, rating REAL NOT NULL, base_impressions INTEGER NOT NULL, active_content_id TEXT, status TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,product_id), UNIQUE(run_id,shop_id,product_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE product_costs(run_id TEXT NOT NULL, product_id TEXT NOT NULL, cost_version INTEGER NOT NULL, unit_cost_vnd INTEGER NOT NULL CHECK(unit_cost_vnd>=0), other_unit_cost_vnd INTEGER NOT NULL, effective_day INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,product_id,cost_version), FOREIGN KEY(run_id,product_id) REFERENCES products(run_id,product_id));
CREATE TABLE inventory(run_id TEXT NOT NULL, product_id TEXT NOT NULL, available_units INTEGER NOT NULL CHECK(available_units>=0), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,product_id), FOREIGN KEY(run_id,product_id) REFERENCES products(run_id,product_id));
CREATE TABLE shop_rules(run_id TEXT NOT NULL, shop_id TEXT NOT NULL, rules_version INTEGER NOT NULL, allow_ads INTEGER NOT NULL, ads_cap_daily_vnd INTEGER NOT NULL, ads_cap_package_vnd INTEGER, voucher_max_pct INTEGER NOT NULL CHECK(voucher_max_pct BETWEEN 0 AND 30), min_profit_per_unit_vnd INTEGER NOT NULL, max_breakeven_roas REAL NOT NULL, require_stop_condition INTEGER NOT NULL, minimum_campaign_stock INTEGER NOT NULL, content_style_notes_json TEXT NOT NULL, effective_day INTEGER NOT NULL, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, confirmation_decision_id TEXT, PRIMARY KEY(run_id,shop_id,rules_version), UNIQUE(run_id,confirmation_decision_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE fee_rules(policy_version TEXT NOT NULL, fee_code TEXT NOT NULL, kind TEXT NOT NULL, rate_bps INTEGER, fixed_vnd INTEGER, basis TEXT NOT NULL, category TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT, is_simulated INTEGER NOT NULL, PRIMARY KEY(policy_version,fee_code), CHECK((rate_bps IS NULL)!=(fixed_vnd IS NULL)));
CREATE TABLE platform_rules(policy_version TEXT NOT NULL, rule_code TEXT NOT NULL, rule_type TEXT NOT NULL, parameters_json TEXT NOT NULL, severity TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT, is_simulated INTEGER NOT NULL, PRIMARY KEY(policy_version,rule_code));
CREATE TABLE run_policies(run_id TEXT PRIMARY KEY REFERENCES runs(run_id), fee_policy_version TEXT NOT NULL, platform_policy_version TEXT NOT NULL, knowledge_release TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE market_daily(run_id TEXT NOT NULL REFERENCES runs(run_id), date TEXT NOT NULL, keyword TEXT NOT NULL, search_volume INTEGER NOT NULL, qualified_listing_count INTEGER NOT NULL, benchmark_cpc_vnd INTEGER NOT NULL, benchmark_ctr_bps INTEGER NOT NULL, benchmark_cvr_bps INTEGER NOT NULL, observed_at TEXT NOT NULL, PRIMARY KEY(run_id,date,keyword));
CREATE TABLE assets(run_id TEXT NOT NULL REFERENCES runs(run_id), asset_id TEXT NOT NULL, shop_id TEXT, product_id TEXT, kind TEXT NOT NULL, object_key TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>0), sha256 TEXT NOT NULL, width INTEGER, height INTEGER, duration_seconds REAL, origin TEXT NOT NULL, source_reference TEXT, visibility TEXT NOT NULL, upload_status TEXT NOT NULL, upload_owner TEXT, created_at TEXT NOT NULL, PRIMARY KEY(run_id,asset_id), FOREIGN KEY(run_id,shop_id,product_id) REFERENCES products(run_id,shop_id,product_id));
CREATE TABLE content_versions(run_id TEXT NOT NULL, content_id TEXT NOT NULL, product_id TEXT NOT NULL, content_version INTEGER NOT NULL, parent_content_id TEXT, title TEXT NOT NULL, description TEXT NOT NULL, cover_options_json TEXT NOT NULL, video_job_json TEXT NOT NULL, feedback_history_json TEXT NOT NULL, style_notes_json TEXT NOT NULL, cover_asset_id TEXT, video_asset_id TEXT, quality_gain REAL NOT NULL, published_day INTEGER, validation_json TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,content_id), UNIQUE(run_id,product_id,content_version), FOREIGN KEY(run_id,product_id) REFERENCES products(run_id,product_id), FOREIGN KEY(run_id,cover_asset_id) REFERENCES assets(run_id,asset_id));
CREATE TABLE negotiations(run_id TEXT NOT NULL, negotiation_id TEXT NOT NULL, shop_id TEXT NOT NULL, day INTEGER NOT NULL, kind TEXT NOT NULL, attempt INTEGER NOT NULL, platform_rounds INTEGER NOT NULL CHECK(platform_rounds<=3), status TEXT NOT NULL, final_proposal_id TEXT, warning_vi TEXT, owner_note_vi TEXT, expected_next_role TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,negotiation_id), UNIQUE(run_id,shop_id,day,attempt), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE proposals(run_id TEXT NOT NULL, proposal_id TEXT NOT NULL, negotiation_id TEXT NOT NULL, shop_id TEXT NOT NULL, product_id TEXT NOT NULL, parent_proposal_id TEXT, proposal_version INTEGER NOT NULL, author_role TEXT NOT NULL, round INTEGER NOT NULL, package_json TEXT, forecast_id TEXT, shared_reason TEXT NOT NULL, stance TEXT NOT NULL, status TEXT NOT NULL, based_on_rules_version INTEGER, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,proposal_id), FOREIGN KEY(run_id,negotiation_id) REFERENCES negotiations(run_id,negotiation_id), FOREIGN KEY(run_id,shop_id,product_id) REFERENCES products(run_id,shop_id,product_id), FOREIGN KEY(run_id,parent_proposal_id) REFERENCES proposals(run_id,proposal_id));
CREATE TABLE forecasts(run_id TEXT NOT NULL, forecast_id TEXT NOT NULL, proposal_id TEXT NOT NULL, product_id TEXT NOT NULL, as_of_day INTEGER NOT NULL, period_start_day INTEGER NOT NULL, period_end_day INTEGER NOT NULL, method_version TEXT NOT NULL, raw_daily_units_json TEXT NOT NULL, daily_point_units_json TEXT NOT NULL, point INTEGER NOT NULL, low INTEGER NOT NULL, high INTEGER NOT NULL, factor_used REAL NOT NULL, stock_warning INTEGER NOT NULL, assumptions_json TEXT NOT NULL, input_fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,forecast_id), FOREIGN KEY(run_id,proposal_id) REFERENCES proposals(run_id,proposal_id));
CREATE TABLE proposal_private_evaluations(run_id TEXT NOT NULL, proposal_id TEXT NOT NULL, evaluation_version INTEGER NOT NULL, rules_version INTEGER NOT NULL, cost_version INTEGER NOT NULL, inventory_version INTEGER NOT NULL, fee_policy_version TEXT NOT NULL, passed INTEGER NOT NULL, violations_json TEXT NOT NULL, unit_contribution_vnd INTEGER NOT NULL, break_even_roas REAL, evaluated_at TEXT NOT NULL, PRIMARY KEY(run_id,proposal_id,evaluation_version), FOREIGN KEY(run_id,proposal_id) REFERENCES proposals(run_id,proposal_id));
CREATE TABLE rule_questions(run_id TEXT NOT NULL, question_id TEXT NOT NULL, shop_id TEXT NOT NULL, external_pref_id TEXT NOT NULL, field TEXT NOT NULL, value_json TEXT NOT NULL, text_vi TEXT NOT NULL, based_on_rules_version INTEGER NOT NULL, status TEXT NOT NULL, answer INTEGER, decision_id TEXT, created_at TEXT NOT NULL, PRIMARY KEY(run_id,question_id), UNIQUE(run_id,shop_id,external_pref_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE cards(run_id TEXT NOT NULL, card_id TEXT NOT NULL, shop_id TEXT NOT NULL, day INTEGER NOT NULL, kind TEXT NOT NULL, proposal_id TEXT, question_id TEXT, forecast_id TEXT, reasons_json TEXT NOT NULL, warnings_json TEXT NOT NULL, notices_json TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,card_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id), FOREIGN KEY(run_id,proposal_id) REFERENCES proposals(run_id,proposal_id), FOREIGN KEY(run_id,question_id) REFERENCES rule_questions(run_id,question_id));
CREATE UNIQUE INDEX one_pending_card ON cards(run_id,shop_id) WHERE status='pending';
CREATE TABLE decisions(run_id TEXT NOT NULL, decision_id TEXT NOT NULL, shop_id TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, target_version INTEGER NOT NULL, action TEXT NOT NULL, edited_package_json TEXT, cover_option TEXT, rule_answer INTEGER, actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, feedback_private TEXT, feedback_shared TEXT, created_at TEXT NOT NULL, PRIMARY KEY(run_id,decision_id), UNIQUE(run_id,target_type,target_id,target_version), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE campaigns(run_id TEXT NOT NULL, campaign_id TEXT NOT NULL, shop_id TEXT NOT NULL, product_id TEXT NOT NULL, proposal_id TEXT NOT NULL, approval_decision_id TEXT NOT NULL, package_snapshot_json TEXT NOT NULL, start_day INTEGER NOT NULL, end_day INTEGER NOT NULL, approved_total_vnd INTEGER NOT NULL, spent_vnd INTEGER NOT NULL CHECK(spent_vnd>=0 AND spent_vnd<=approved_total_vnd), low_roas_streak INTEGER NOT NULL, status TEXT NOT NULL, ads_status TEXT NOT NULL, ads_stop_reason TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,campaign_id), UNIQUE(run_id,proposal_id), UNIQUE(run_id,approval_decision_id), FOREIGN KEY(run_id,shop_id,product_id) REFERENCES products(run_id,shop_id,product_id), FOREIGN KEY(run_id,proposal_id) REFERENCES proposals(run_id,proposal_id), FOREIGN KEY(run_id,approval_decision_id) REFERENCES decisions(run_id,decision_id));
CREATE UNIQUE INDEX one_active_campaign ON campaigns(run_id,product_id) WHERE status='active';
CREATE TABLE shop_runtime(run_id TEXT NOT NULL, shop_id TEXT NOT NULL, cooldown_until_day INTEGER NOT NULL, seller_renegotiations INTEGER NOT NULL, active_negotiation_id TEXT, pending_card_id TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,shop_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE content_jobs(run_id TEXT NOT NULL, job_id TEXT NOT NULL, shop_id TEXT NOT NULL, product_id TEXT NOT NULL, proposal_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK(attempt BETWEEN 1 AND 3), brief_json TEXT NOT NULL, feedback_history_json TEXT NOT NULL, style_notes_json TEXT NOT NULL, input_asset_ids_json TEXT NOT NULL, provider TEXT NOT NULL, provider_job_id TEXT, cache_key TEXT NOT NULL, status TEXT NOT NULL, output_content_ids_json TEXT NOT NULL, fallback_used INTEGER NOT NULL, error_code TEXT, lease_until TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,job_id), UNIQUE(run_id,proposal_id,attempt), FOREIGN KEY(run_id,proposal_id) REFERENCES proposals(run_id,proposal_id), FOREIGN KEY(run_id,shop_id,product_id) REFERENCES products(run_id,shop_id,product_id));
CREATE TABLE day_settlements(run_id TEXT NOT NULL, settlement_id TEXT NOT NULL, shop_id TEXT NOT NULL, day INTEGER NOT NULL, input_snapshot_hash TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,settlement_id), UNIQUE(run_id,shop_id,day), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE daily_metrics(run_id TEXT NOT NULL, product_id TEXT NOT NULL, date TEXT NOT NULL, day INTEGER NOT NULL, shop_id TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('organic','paid')), campaign_id TEXT, content_id TEXT NOT NULL, impressions INTEGER NOT NULL CHECK(impressions>=0), clicks INTEGER NOT NULL CHECK(clicks>=0 AND clicks<=impressions), orders INTEGER NOT NULL CHECK(orders>=0 AND orders<=clicks), units INTEGER NOT NULL CHECK(units=orders), net_revenue_vnd INTEGER NOT NULL, ad_spend_vnd INTEGER NOT NULL CHECK(ad_spend_vnd>=0), fees_vnd INTEGER NOT NULL, cogs_vnd INTEGER NOT NULL, other_cost_vnd INTEGER NOT NULL, contribution_vnd INTEGER NOT NULL, rounding_adjustment_vnd INTEGER NOT NULL, realized_roas REAL, fee_policy_version TEXT NOT NULL, cost_version INTEGER NOT NULL, settlement_id TEXT, source TEXT NOT NULL CHECK(source IN ('seeded','simulated')), created_at TEXT NOT NULL, PRIMARY KEY(run_id,product_id,date,channel), FOREIGN KEY(run_id,shop_id,product_id) REFERENCES products(run_id,shop_id,product_id), FOREIGN KEY(run_id,content_id) REFERENCES content_versions(run_id,content_id), FOREIGN KEY(run_id,campaign_id) REFERENCES campaigns(run_id,campaign_id), FOREIGN KEY(run_id,settlement_id) REFERENCES day_settlements(run_id,settlement_id), CHECK(channel!='organic' OR (ad_spend_vnd=0 AND realized_roas IS NULL)));
CREATE TABLE events(run_id TEXT NOT NULL REFERENCES runs(run_id), seq INTEGER NOT NULL, day INTEGER NOT NULL, type TEXT NOT NULL, actor_role TEXT NOT NULL, shop_id TEXT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, visibility TEXT NOT NULL, payload_json TEXT NOT NULL, text_vi TEXT NOT NULL, recorded_at TEXT NOT NULL, simulated_at TEXT NOT NULL, PRIMARY KEY(run_id,seq), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE operations(run_id TEXT NOT NULL REFERENCES runs(run_id), operation_id TEXT NOT NULL, day INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, result_json TEXT, error_code TEXT, lease_until TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,operation_id), UNIQUE(run_id,day,kind));
CREATE TABLE learning_handoffs(run_id TEXT NOT NULL REFERENCES runs(run_id), day INTEGER NOT NULL, settlement_cursor INTEGER NOT NULL, status TEXT NOT NULL, night_summary_json TEXT, memory_report_asset_id TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(run_id,day));
CREATE TABLE knowledge_documents(document_id TEXT NOT NULL, document_version INTEGER NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, collection_scope TEXT NOT NULL, owner_run_id TEXT, owner_shop_id TEXT, source_object_key TEXT NOT NULL, provider_file_id TEXT, vector_store_id TEXT, index_status TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT, is_simulated INTEGER NOT NULL, source_url TEXT, source_collected_at TEXT, checksum TEXT NOT NULL, knowledge_release TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(document_id,document_version), CHECK((collection_scope='shared' AND owner_run_id IS NULL AND owner_shop_id IS NULL) OR (collection_scope='shop_private' AND owner_run_id IS NOT NULL AND owner_shop_id IS NOT NULL)));
CREATE TABLE idempotency_records(principal_id TEXT NOT NULL, run_scope TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL, operation_id TEXT, lease_until TEXT, response_status INTEGER, response_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(principal_id,run_scope,method,path,key));
CREATE TABLE comparison_groups(group_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, run_on_id TEXT NOT NULL REFERENCES runs(run_id), run_off_id TEXT NOT NULL REFERENCES runs(run_id), scenario_version TEXT NOT NULL, simulator_version TEXT NOT NULL, seed INTEGER NOT NULL, days INTEGER NOT NULL, report_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX events_day ON events(run_id,shop_id,seq);
CREATE INDEX proposals_status ON proposals(run_id,shop_id,status);
CREATE INDEX metrics_day ON daily_metrics(run_id,shop_id,date);
CREATE INDEX jobs_status ON content_jobs(run_id,status);
